class Solution {
    public void flatten(TreeNode root) {
        TreeNode cur = root;
        while (cur != null) {
            if (cur.left != null) {
                TreeNode pre = cur.left;
                while (pre.right != null) {         // 左子树最右边的节点
                    pre = pre.right;
                }
                pre.right = cur.right;              // 原来的右子树接到它后面
                cur.right = cur.left;               // 左子树挪到右边
                cur.left = null;                    // 断开左指针
            }
            cur = cur.right;
        }
    }
}

