            prevPtr: prevBackup,
            newHead: true,
            animHead: old !== null,
            extra: old !== null ? [{ from: id, to: old, cls: "on", anim: "draw", bend: 0.35, label: "right" }] : [],
          }),
          { at: "linkR", facts: [["当前 node", nd.v], ["prev", oldName]] },
