          "node.left = None",
          hadLeft ? `断开 ${nd.v} 原来的左指针（${nd.v}.left = None），避免树里留下分支或环。` : `${nd.v}.left 置空（本来就是空）。`,
          view(id, {
            prevPtr: prevBackup,
            cutEdges: hadLeft ? [[id, nd.l]] : [],
          }),
          { at: "clearL", facts: [["当前 node", nd.v], ["prev", oldName]] },
        );
        nd.l = null;

        snap(
          "prev = node",
